import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/software-exam/ispm/project-cost-management/comprehensive-exercises/","title":"8 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"8 综合练习","createTime":"2026-11-22T21:20:00.000Z","permalink":"/software-exam/ispm/project-cost-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":85.62,"words":25687},"git":{"createdTime":1795354081000},"filePathRelative":"software-exam/ispm/project-cost-management/8.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`8.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 发生成本失控的原因主要包括：（ ）。①对工程项目认识不足；②组织制度不健全；③方法问题；④技术的制约；⑤需求管理不当</p><ul><li>A．①②③④</li><li>B．①②③⑤</li><li>C．①②④⑤</li><li>D．①②③④⑤</li></ul><details class="quiz" data-q="1" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：成本失控的原因：①对工程项目认识不足；②组织制度不健全；③方法问题；④技术的制约⑤需求管理不当（P335）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 关于成本管理的描述，不正确的是（ ）。</p><ul><li>A．在项目过程中，不应只关心完成项目活动所需资源的成本，也需考虑项目决策对项目最终产品的使用和维护成本的影响</li><li>B．成本估算和成本预算是两个过程，即使是很小的项目，也需要由不同的人员来分别完成，以保证估算和预算过程的客观性和独立性</li><li>C．全生命周期成本管理经常与价值工程技术结合使用，用于降低成本，缩短时间，提高项目可交付成果的质量和绩效，并优化决策过程</li><li>D．项目成本管理应当考虑项目干系人的需要，不同的项目干系人可能在不同的时间以不同的方式测算项目的成本</li></ul><details class="quiz" data-q="2" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：就某些项目，特别是小项目而言，成本估算和成本预算之间的关系极其密切，以致可以将其视为一个过程，由一个人在较短的时间内完成（P334）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 过去的决策已经发生了，不能由现在或将来的任何决策改变的成本是（ ）</p><ul><li>A．沉没成本</li><li>B．机会成本</li><li>C．间接成本</li><li>D．直接成本</li></ul><details class="quiz" data-q="3" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：沉没成本：指由于过去的决策已经发生的，面不能由现在或将来的任何决策改变的成本。沉没成本是一种历史成本，对现有决策而言是不可控成本（P336）　<span class="quiz-src">教材第 11 章章节习题</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> 以下关于成本管理的说法中不正确的是（ ）。</p><ul><li>A．项目全过程所耗用的各种成本的总和为项目成本</li><li>B．对于一个项目而言，产品的全生命期成本考虑的是权益总成本，即开发成本加上维护成本</li><li>C．在项目过程中不应只关心完成项目活动所需资源的成本，也应该考虑项目决策对项目最终产品的使用和维护成本的影响。</li><li>D．具体的成本一般包括直接工时、其他直接费用、间接工时、采购价格，不包括其他间接费用。</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：具体的成本一般包括直接工时、其他直接费用、间接工时、其他间接费用以及采购价格（P335）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 关于应急储备和管理储备的说法中不正确的是（ ）。</p><ul><li>A．应急储备包含在成本基准中，用来应对已知-未知的风险</li><li>B．管理储备不包含在成本基准中，用来应对未知-未知的风险</li><li>C．项目经理可以调用应急储备，它通常是项目总预算的一部分</li><li>D．项目经理无权调用管理储备，因为管理储备不在成本基准之中，所以使用管理储备，成本基准不会受到影响</li></ul><details class="quiz" data-q="5" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：管理储备不包括在成本基准中，但属于项目总预算和资金需求的一部分，使用前需要得到高层管理者审批。当动用管理储备资助不可预见的工作时，就要把动用的管理储备增加到成本基准中，此时公导致成本基准的变更（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 税金、额外福利和保卫费用等属于（ ）。</p><ul><li>A．可变成本</li><li>B．固定成本</li><li>C．间接成本</li><li>D．机会成本</li></ul><details class="quiz" data-q="6" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：间接成本：来自一般管理费用科目或几个项目共同担负的项目成本所分摊给本项目的费用，就形成了项目的间接成本，如税金、额外福利和保卫费用等（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 关于成本的描述，不正确的是（ ）。</p><ul><li>A．办公场地的物业费、保安费是多个项目共同担负的成本，属于间接成本</li><li>B．沉没成本是一种历史成本，在投资决策时应充分考虑沉没成本</li><li>C．应急储备可取成本估算值的某一百分比、某个固定值来确定</li><li>D．管理储备用于不可预见的工作时，需要把所用的管理储备增加到成本基准中</li></ul><details class="quiz" data-q="7" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：沉没成本：指由于过去的决策已经发生的，而不能由现在或将来的任何决策改变的成本。沉设成本是一种历史成本，对现有决策面言是不可控成本，会很大程度上影响人们的行为方式与决策，在投资决策时应排除沉没成本的干扰（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 关于成本管理，不正确的是（ ）。</p><ul><li>A．成本管理的日的是确保在批准的预算内完成项目</li><li>B．在某些小项目中，成本估算和成本预算过程可以合并</li><li>C．项目团队工资属于直接成本，差旅费属于间接成本</li><li>D．应急储备包括在成本基准中</li></ul><details class="quiz" data-q="8" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：直接成本：直接可以归属于项目工作的成本为直接成本。如项目团队差旅费、工资、项目使用的物料及设备使用费等（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 关于成本的描述，不正确的是（ ）。</p><ul><li>A．额外福利、项目团队的差旅费属于直接成本</li><li>B．税金、人力资源部门员工工资、保险费属于间接成本</li><li>C．项目总预算为成本基准与管理储备之和</li><li>D．应急储备是包含在成本基准内的一部分预算</li></ul><details class="quiz" data-q="9" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：关于B为什么正确，大家看清楚，题目说的是人力资源部门员工工资，这个确实是间接成本。可变成本 随着生产量、工作量或时间而变的成本为可变成本，又称变动成本固定成本 不随生产量、工作量或时间的变化而变化的非重复成本为固定成本直接可以归属于项目工作的成本为直接成本（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> 关于成本的描述，正确的是（ ）。</p><ul><li>A．在投资决策时应避免受到沉没成本的干扰</li><li>B．项目团队差旅费、工资、物料费属于间接成本</li><li>C．管理储备是用于应对已识别风险</li><li>D．管理储备是包含在成本基准内的一部分预算</li></ul><details class="quiz" data-q="10" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A正确。沉没成本：指由于过去的决策已经发生了的，而不能由现在或将来的任何决策改变的成本。沉没成本是一种历史成本，对现有决策而言是不可控成本，会很大程度上影响人们的行为方式与决策，在投资决策时应排除沉没成本的于扰（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 关于成本类型的描述，不正确的是（ ）。</p><ul><li>A．项目团队差旅费、工资、税金、物料及设备使用费为直接成本</li><li>B．随着生产量、工作量或时间而变的成本称为变动成本</li><li>C．利用一定时间或资源生产一种商品时，便失去了使用这些资源生产其他最佳替代品的机会，称为机会成本</li><li>D．沉没成本是一种历史成本，对现有决策而言是不可控成本</li></ul><details class="quiz" data-q="11" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A不正确，税金是间接成本。间接成本：来自一般管理费用科目或几个项目共同担负的项目成本所分摊给本项目的费用，就形成了项目的间接成本，如税金、额外福利和保卫费用等（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 关于成本的描述，不正确的是（ ）。</p><ul><li>A．投资决策时应尽量考虑沉没成本</li><li>B．沉没成本是一种历史成本</li><li>C．管理储备不包括在成本基准中</li><li>D．管理储备是项目总预算的一部分</li></ul><details class="quiz" data-q="12" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：沉没成本：指由于过去的决策已经发生了的，而不能由现在或将来的任何决策改变的成本沉没成本是一种历史成本，对现有决策而言是不可控成本，会很大程度上影响人们的行为方式与决策，在投资决策时应排除沉没成本的于扰（P336）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 在进行成本估算时，（ ）不是直接成本。</p><ul><li>A．项目人员的工资</li><li>B．项目所用的材料</li><li>C．电费</li><li>D．分包商的费用</li></ul><details class="quiz" data-q="13" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：电费一般为多个项目共同分摊。直接成本：直接可以归属于项目工作的成本为直接成本。如项目团队差旅费、工资、项目使用的物料及设备使用费等（P336）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 关于项目成本管理过程的相关描述，不正确的是（ ）。</p><ul><li>A．管理储备是为了管理控制的目的而特别留出的项目预算，属于项目总预算和资金需求的一部分，用来应对会影响项目的“未知-未知”风险</li><li>B．当动用管理储备资助不可预见的工作时，就要把动用的管理储备增加到成本基准中，此时会导致成本基准的变更</li><li>C．应急储备是不包含在成本基准内的预算，用来应对那些会影响项目的“已知一未知”风险，以及已经制定应急或减轻措施的已识别风险</li><li>D．预知有些项目可交付成果需要返工，却不知道返工的工作量是多少，可以预留应急储备来应对这些未知数量的返工工作</li></ul><details class="quiz" data-q="14" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：应急储备是包含在成本基准内的一部分预算，用来应对已经接受的已识别风险，以及已经制定应急或减轻措施的已识别风险（P336）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 挣得进度偏差的计算公式是（ ）。</p><ul><li>A．SV(t)=AS-AT</li><li>B．SV(t)=AS-VT</li><li>C．SV(t)=ES-VT</li><li>D．SV(t)=ES-AT</li></ul><details class="quiz" data-q="15" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：挣得进度理论用ES和实际时间(AT)替代了传统EVM所使用的进度偏差测量指标SV（挣值-计划价值）。使用这种替代方法计算进度偏差ES-AT（P337）　<span class="quiz-src">自编</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 挣得进度绩效SPI(t)&gt;1，代表的意思是（ ）。</p><ul><li>A．进度超前</li><li>B．进度落后</li><li>C．成本超支</li><li>D．成本节约</li></ul><details class="quiz" data-q="16" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：进度绩效指数：SPI(t)-ES/AT,SPI(t)&gt;1，进度超前；SPI(t)山，进度落后（P337）　<span class="quiz-src">自编</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 关于项目成本管理基础、挣得进度及相关要求，正确的是（ ）</p><ul><li>A．挣值管理(EVM)是将计划工作、实际成本、实际完成工作转换成时间进行比较</li><li>B．挣得进度(ES)是截止到某时间点，实际完成工作量原计划所需的时间</li><li>C．挣得进度偏差SV(t)=AT-ES,SV(t)&gt;0表示进度超前</li><li>D．详细的成本估算适用于范围未明确、易发生变更的长期项目规划</li></ul><details class="quiz" data-q="17" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A不正确。挣值管理(EVM)是将计划工作、实际成本、实际完成工作转换成货币进行比较；挣得进度才是用时间作为比较单位。B正确（P336-338）　<span class="quiz-src">自编</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> 项目成本管理过程不包括（ ）。</p><ul><li>A．规划成本管理</li><li>B．估算成本</li><li>C．结算成本</li><li>D．控制成本</li></ul><details class="quiz" data-q="18" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目成本管理过程包括规划成本管理、估算成本、制定预算、控制应本（P337-338）　<span class="quiz-src">教材第 11 章章节习题</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 成本管理中，需要裁剪的考虑因素不包括（ ）。</p><ul><li>A．成本控制</li><li>B．估算和预算</li><li>C．挣值管理</li><li>D．治理</li></ul><details class="quiz" data-q="19" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：由于每个项目都是独特的，项目经理可能根据需要裁剪项目成本管理过程，裁剪时应考虑的因素包括：知识管理，估算和预算，挣值管理，敏捷方法的使用，治理（P338）　<span class="quiz-src">自编</span></p></details><p><a id="q20" class="quiz-anchor"></a></p><p><strong>20.</strong> 成本管理中，需要裁剪的考虑因素不包括（ ）。</p><ul><li>A．知识管理</li><li>B．成本控制</li><li>C．挣值管理</li><li>D．敏捷方法的使用</li></ul><details class="quiz" data-q="20" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：由于每个项目都是独特的，项目经理可能根据需要裁剪项目成本管理过程，裁剪时应考虑的因素包括：知识管理，估算和预算，挣值管理，敏捷方法的使用，治理（P338）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 以下关于成本管理的说法中不正确的是（ ）。</p><ul><li>A．对易变性高、范围并未完全明确、经常发生变更的项目，详细的成本计算一定要有</li><li>B．详细的估算适用于采用准时制的短期规划，</li><li>C．如果易变的项目也遵循严格的预算，通常需要更频繁地更改范围和进度计划，确保始终保持在成本制约因素之内。</li><li>D．采用轻量级估算方法适合经常发生变更的项目。</li></ul><details class="quiz" data-q="21" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：对易变性高、范围并未完全明确、经常发生变更的项目，详细的成本计算可能没有多大帮助在这种情况下，可以采用轻量级估算方法快速生成对项目人力成本的高层级预测，这样在出现变更时容易调整预测；而详细的估算适用于采用准时制的短期规划（P338）　<span class="quiz-src">自编</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 以下关于成本管理的说法中不正确的是（ ）。</p><ul><li>A．对易变性高、范围并未完全明确、经常发生变更的项目，详细的成本计算可能没有多大帮助。</li><li>B．详细的估算适用于采用准时制的短期规划。</li><li>C．如果易变的项目也遵循严格的预算，通常需要更频紫地更改范围和进度计划，确保始终保持在成本制约因素之内。</li><li>D．轻量级估算方法不适合对项目人力成本的高层级预测。</li></ul><details class="quiz" data-q="22" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：对易变性高、范围并未完全明确、经常发生变更的项目，详细的成本计算可能没有多大帮助在这种情况下，可以采用轻量级估算方法快速生成对项目人力成本的高层级预测，这样在出现变更时容易调整预测；而详细的估算适用于采用准时制的短期规划如果易变的项目也遵循严格的预算，通常需要更频繁地更改范围和进度计划，确保始终保持在成本制约因素之内（P338）　<span class="quiz-src">自编</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 关于项目成本管理过程的描述，不正确的是（ ）。</p><ul><li>A．项目成本管理包括规划成本管理、估算成本、制定预算、控制成本四个过程</li><li>B．对易变性高、范围并未完全明确、经常发生变更的项目，必须要进行详细的成本计算</li><li>C．项目经理可根据需要裁剪项目成本管理过程，裁剪时应考虑知识管理、估算和预算、挣值管理、敏捷方法的使用和治理等因素</li><li>D．在项目实际进展中，项目成本管理的各过程会相互交叠和相互作用</li></ul><details class="quiz" data-q="23" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：对易变性高、范围并未完全明确、经常发生变更的项目，详细的成本计算可能没有多大帮助在这种情况下，可以采用轻量级估算方法快速生成对项目人力成本的高层级预测，这样在出现变更时容易调整预测；而详细的估算适用于采用准时制的短期规划（P338）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 某企业董事会讨论全年重大项目成本管理计划，为控制风险，要求每个项目可接受的成本区间为不超过±5%，这属于成本管理计划中（ ）的规定。</p><ul><li>A．精确度</li><li>B．绩效测量规则</li><li>C．绩效测量规划</li><li>D．准确度</li></ul><details class="quiz" data-q="24" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：O。●精确度：根据活动范围和项目规模，设定成本估算向上或向下取整的程度（例如995.59元取整为 1000元）。●准确度：为活动成本估算规定一个可接受的区间（如土10%），其中可能包括一定数量的应急储盈（P34）　<span class="quiz-src">教材第 11 章章节习题</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 规划成本管理是确定如何（ ）和控制项目成本的过程。</p><ul><li>A．估算、明确、管理、监督</li><li>B．明确、预算、管理、监督</li><li>C．估算、预算、管理、监督</li><li>D．估算、预算、明确、监督</li></ul><details class="quiz" data-q="25" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：338。规划成本管理是确定如何估算、预算、管理、监督和控制项目成本的过程　<span class="quiz-src">自编</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 规划成本管理时不需要考虑的因素是（ ）。</p><ul><li>A．项目章程</li><li>B．风险管理计划</li><li>C．进度管理计划</li><li>D．成本管理计划</li></ul><details class="quiz" data-q="26" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：其实就是问的规划成本管理的输入，显然D错误。规划成本管理的输入包括：1.项目章程2.项目管理计划（进度管理计划、风险管理计划）;3.事业环境因素；4.组织过程资产（P339）　<span class="quiz-src">自编</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 成本管理计划中，人时数、人天数指的是（ ）。</p><ul><li>A．计量单位</li><li>B．精确度</li><li>C．准确度</li><li>D．控制临界值</li></ul><details class="quiz" data-q="27" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：计量单位。需要规定每种资源的计量单位，例如，用于测量时间的人时数、人天数或周数，用于计量数量的米、升、吨、千米或立方码，或者用货币表示的总价（P340）　<span class="quiz-src">自编</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 成本管理计划中，某项目的估算成本为995.59元，指的是（ ）。</p><ul><li>A．计量单位</li><li>B．精确度</li><li>C．准确度</li><li>D．控制临界值</li></ul><details class="quiz" data-q="28" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。精确度。根据活动范围和项目规模，设定成本估算向上或向下取整的程度（例如995.59元取整为 1OOO元）（P34）　<span class="quiz-src">自编</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 以下不属于成本管理计划的内容的是（ ）。</p><ul><li>A．成本报告的格式</li><li>B．确定拟用的EVM技术</li><li>C．资源分解结构</li><li>D．组织程序链接</li></ul><details class="quiz" data-q="29" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：成本管理计划中一般需要规定：计量单位；精确度；准确度；组织程序链接；控制临界值：绩效测量规则；报告格式；其他细节（P340）　<span class="quiz-src">自编</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 成本管理计划中一般不包含（ ）。</p><ul><li>A．组织程序链接</li><li>B．计量单位</li><li>C．项目里程碑</li><li>D．控制临界值</li></ul><details class="quiz" data-q="30" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：在成本管理计划中一般需要规定：计量单位；精确度；准确度；组织程序链接；控制临翠值：绩效测量规则；报告格式；其他细节（P340-341）　<span class="quiz-src">自编</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 关于规划成本管理的描述，不正确的是（ ）。</p><ul><li>A．进度管理计划提供了影响成本估算和管理的过程及控制方法</li><li>B．风险管理计划提供了识别、分析和监督相关风险的方法</li><li>C．规划成本管理过程的主要作用是确定项目所需的资金</li><li>D．规划成本管理过程仅开展一次或仅在项目的预定点开展</li></ul><details class="quiz" data-q="31" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：规划成本管理是确定如何估算、预算、管理、监督和控制项目成本的过程。本过程的主要作用是在整个项目期间为如何管理项目成本提供指南和方向（P338）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 在项目成本管理中，规划成本管理过程的输入包括（ ）。</p><ul><li>A．进度管理计划和成本基准</li><li>B．成本管理计划和成本基准</li><li>C．进度管理计划和风险管理计划</li><li>D．进度管理计划和成本管理计划</li></ul><details class="quiz" data-q="32" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：规划成本管理过程的输入：1项目章程；2.项目管理计划（进度管理计划·风险管理计划）3.事业环境因素 4.组织过程资产（P339）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 规划成本管理的作用是（ ）。</p><ul><li>A．直接控制项目所有支出</li><li>B．确定项目最终实际成本</li><li>C．对完成项目工作所需资金进行近似估算</li><li>D．为如何管理项目成本提供指南和方向</li></ul><details class="quiz" data-q="33" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：规划成本管理是确定如何估算、预算、管理、监督和控制项目成本的过程。本过程的主要作用是在整个项目期间为如何管理项目成本提供指南和方向（P338）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 项目成本核算中使用到的WBS组成部分称为（ ），它拥有唯一的编码或账号，直接与执行组织的会计制度相联系。</p><ul><li>A．工作包</li><li>B．控制账户</li><li>C．WBS字典</li><li>D．规划包</li></ul><details class="quiz" data-q="34" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：在项目成本核算中使用的WBS组成部分称为控制账亡，每个控制账户都有唯一的编码或账号，直接与执行组织的会计制度相联系（P340）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 以下（ ）属于成本管理计划的内容。</p><ul><li>A．控制临界值</li><li>B．成本估算</li><li>C．项目资金需求</li><li>D．成本基准</li></ul><details class="quiz" data-q="35" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：在成本管理计划中一般需要规定计量单位、精确度、准确度、组织程序链接、控制临界值、绩效测量规则、报告格式和其他细节等（P340）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> 成本管理计划中通常不会规定（ ）。</p><ul><li>A．精确度</li><li>B．准确度</li><li>C．控制临界值</li><li>D．薪酬结构</li></ul><details class="quiz" data-q="36" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：成本管理计划中一般需要规定：计量单位；确度；准确度；组织程序链接；控制临界值：绩效测量规则；报告格式；其他细节（P340）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 以下工具与技术中，（ ）不能用于规划成本管理。</p><ul><li>A．专家判断</li><li>B．成本汇总</li><li>C．备选方案分析</li><li>D．会议</li></ul><details class="quiz" data-q="37" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。规划成本管理的工具技术：专家判断、数据分析（备选方案分析）、会议（P34）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 不属于成本管理计划的核心的是（ ）</p><ul><li>A．成本的实际支出记录</li><li>B．成本估算的精度要求</li><li>C．成本偏差的控制临界值</li><li>D．处理汇率波动的程序</li></ul><details class="quiz" data-q="38" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：O。成本管理计划的内容包括：①计量单位；②精确度；③准确度；④组织程序链接；⑤控制临界值；⑥绩效测量规则(EVM);⑦报告格式；⑥其他细节（对战略筹资方案的说明；处理汇率波动的程序；记录项目成本的程序等）（P34）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 三点估算中贝塔分布的计算公式为（ ）。</p><ul><li>A．CE=(Co+Cm+Cp)/3</li><li>B．CE=(Co+4Cm+Cp)/6</li><li>C．CE=(Co+Cm+Cp)/6</li><li>D．CE=(Co+4Cm+Cp)/3</li></ul><details class="quiz" data-q="39" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：送分题，这个要是不会那就实在没办法了（P343）　<span class="quiz-src">教材第 11 章章节习题</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 下列活动中需要在整个项目期间定期开展的是（ ）。</p><ul><li>A．规划成本管理</li><li>B．估算成本</li><li>C．制定预算</li><li>D．控制成本</li></ul><details class="quiz" data-q="40" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：估算成本是定期开展（P341）　<span class="quiz-src">自编</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> 关于项目成本相关内容的描述，不正确的是（ ）。</p><ul><li>A．成本估算的准确性随着项目的进展而提高</li><li>B．项目成本预算和估算的准确度可能影响项目成本基准</li><li>C．即使项目团队成员都很有经验，也可能会有学习曲线造成的成本</li><li>D．进行成本估算，可以不考虑针对项目收费的全部资源</li></ul><details class="quiz" data-q="41" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：进行成本估算，应该考虑针对项目收费的全部资源，一般包括人工、材料、设备、服务、设施，以及一些特殊的成本种类，如通货膨胀补贴、融资成本或应急成本（P341）　<span class="quiz-src">自编</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> 关于成本估算的描述，不正确的是（ ）。</p><ul><li>A．成本估算时应考虑管理成本、房屋租金、保险等非直接成本</li><li>B．在项目生命周期内，项目估算的准确性随着项目的进展而降低</li><li>C．项目团队成员学习过程所引起的成本应该被纳入项目成本中</li><li>D．应急储备和管理储备应被计入项目成本中</li></ul><details class="quiz" data-q="42" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B不正确，项目估算的准确性亦将随着项目的进展面逐步提高（P341）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> 以下关于成本估算的说法错误的是（ ）。</p><ul><li>A．成本一般用货币单位（人民币、美元、欧元、日元）来表示</li><li>B．针对项目使用的所有资源来估算计划活动成本</li><li>C．一般不考虑关于风险应对方面的信息</li><li>D．估算完成每项计划活动所需的资源的近似成本</li></ul><details class="quiz" data-q="43" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：风险登记册是成本估算的依据。风险登记册：包含已识别并按优先顺序排列的单个项目风险的详细信息及针对这些风险采取的应对措施（P342）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> 估算成本过程的依据中，项目管理计划中的（ ）描述了估算方法以及成本估算需要达到的准确度和精确度；项目文件中的（ ）可以帮助提高成本估算的准确度和精确度；（ ）明确了每个工作包或活动所需的资源类型和数量，是成本估算的重要依据。</p><ul><li>A．成本管理计划、风险登记册、资源需求</li><li>B．质量管理计划、经验教训登记册、项目进度计划</li><li>C．成本管理计划、经验教训登记册、资源需求</li><li>D．质量管理计划、风险登记册、项目进度计划</li></ul><details class="quiz" data-q="44" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：估算成本的输入中，项目管理计划里的成本管理计划，明确描述了估算方法以及成本估算需要达到的准确度和精确度；项目文件中的经验教训登记册，有关的经验教训可以运用到项目后期阶段，以提高成本估算的准确度和精确度；资源蛋求则明确了每个工作包或活动所需的资激类型和数量，是成本估算的重要依据（P342）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 在项目成本估算技术中，自下而上估算的准确性及其本身所需的成本，通常取决于（ ）</p><ul><li>A．估算专家</li><li>B．单个活动或工作包的规模和复杂程度</li><li>C．参数模型的可靠性</li><li>D．WBS分解的颗粒度</li></ul><details class="quiz" data-q="45" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：自下而上估算是对工作组成部分进行估算的一种方法，首先对单个工作包或活动的成本进行最具体、细致的估算，然后把这些细节性成本向上汇总或“滚动”到更高层次，用于后续报告和跟踪（P343）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> （ ）的准确性取决于模型的成熟度和基础数据的可靠性</p><ul><li>A．类比估算</li><li>B．三点估算</li><li>C．自下而上估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="46" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：参数估算的准确性取决于参数模型的成熟度和基础数据的可靠性（P343）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> （ ）通过考虑估算中的不确定性与风险，便用三种估算值来界定活动成本的近似区间，可以提高活动成本估算的准确性。</p><ul><li>A．类比估算</li><li>B．三点估算</li><li>C．参数估算</li><li>D．专家判断</li></ul><details class="quiz" data-q="47" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：三点估算通过考虑估算中的不确定性与风险，使用三种估算值来界定活动成本的近似区间可以提高单点成本估算的准确性（P343）　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> 关于成本估算相关技术的描述，正确的是（ ）。</p><ul><li>A．参数估算中会使用到历史数据，因此比类比估算的准确性要高</li><li>B．参数估算适合在项目的早期阶段详细信息不足时采用</li><li>C．类比估算法通常成本较高、耗时较多</li><li>D．类比估算既可以针对整个项目，也可以针对项目中的某个部分</li></ul><details class="quiz" data-q="48" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：选项A错误。虽然参数估算用历史数据，但“用历史数据”不是精度高的绝对原因——参数估算的准确性还依赖“参数关系是否靠谱”“当前项目参数是否明确”（P343）　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 以下（ ）不属于成本估算的工具和技术。</p><ul><li>A．备选方案分析</li><li>B．类比估算</li><li>C．参数估算</li><li>D．挣值分析</li></ul><details class="quiz" data-q="49" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：成本估算的工具和技术：1专家判断；2.类比估算；3参数估算；4.自下而上估算；5三点估算；6.数据分析；7.项目管理信息系统；8.决策（P343-344）　<span class="quiz-src">自编</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 关于估算成本的工具技术、输出及相关要求，正确的是（ ）</p><ul><li>A．类比估算可以针对项目中的某个部分估算，但是无法针对整个项目进行估算</li><li>B．储备分析中，应急储备是成本基准的一部分，可根据项目信息变化调整</li><li>C．成本估算需覆盖人工、材料、设备等直接成本，管理成本无需考虑</li><li>D．项目管理信息系统是估算成本过程的输入，能帮助辅助成本估算</li></ul><details class="quiz" data-q="50" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：A不正确。类比估算可以针对整个项目或项目中的某个部分，并可与其他估算方法联合使用。B正确。储备分析中，应急值备是成本基准的一部分，也是项目整体资金需求的一部分，随着项目信息越来越明确，可以动用、减少或取消应急储备（P343-344）　<span class="quiz-src">自编</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> 关于成本管理的描述，正确的是（ ）。</p><ul><li>A．应急储备可取成本估算值的某一百分比、某个固定值来确定</li><li>B．项目进度发生变化但范围没有变化，对成本估算不产生影响</li><li>C．项目经理无权调用管理储备，因为管理储备不在成本基准之中，所以使用管理储备后成本基准不会受到影响</li><li>D．沉没成本是一种历史成本，在投资决策时应充分考虑沉没成本</li></ul><details class="quiz" data-q="51" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：B错误。P344。进度变化可能会涉及赶工，需要增加成本等；C错误。使用管理储备后，成本基准就会跟着变化，所以需要更新成本基准；D错误（P336）　<span class="quiz-src">自编</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> 关于成本估算的描述，不正确的是（ ）。</p><ul><li>A．成本估算应识别和考虑各种成本计算方案</li><li>B．成本估算应考虑项目工期要求和质量要求对成本的影响</li><li>C．成本估算时应同时考虑应急储备和管理储备</li><li>D．估算依据应清晰、完整地说明估算是如何编制的</li></ul><details class="quiz" data-q="52" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：为应对成本的不确定性，成本估算中可以包括应急储备。应急储备是包含在成本基准内的一部分预算，用来应对已经接受的已识别风险，以及已经制定应急或减轻措施的已识别风险（P344）　<span class="quiz-src">自编</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 下列说法不正确的是（ ）。</p><ul><li>A．为应对成本的不确定性，成本估算中可以包括管理储备</li><li>B．成本估算的输出包括估算依据</li><li>C．成本类比估算使用以往类似项目的参数值或属性来估算</li><li>D．参数估算其准确性取决于参数模型的成熟度和基础数据的可靠性</li></ul><details class="quiz" data-q="53" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：为应对成本的不确定性，成本估算中可以包括应急储备（P344）　<span class="quiz-src">自编</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 某项目计划分为立项、实施和运维三个阶段。财务部给该项目的预算金额不超过80万元。项目经理估算立项阶段的成本为20万元，实施阶段的成本为50万元，运维阶段的成本为30万元若用自底向上法对该项目的成本进行估算，则估算值应为（ ）万元。</p><ul><li>A．zO</li><li>B．80</li><li>C．90</li><li>D．100</li></ul><details class="quiz" data-q="54" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「100」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 分析成本构成结果，找出各种可以相互替代的成本，协调各种成本之间的关系，属于（ ）的内容。</p><ul><li>A．识别和分析项目成本构成科目</li><li>B．成本估算</li><li>C．成本预算</li><li>D．成本审评</li></ul><details class="quiz" data-q="55" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「成本估算」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 为了加强预算控制，成本估算应在WBS的（ ）层进行。</p><ul><li>A．最高</li><li>B．最低</li><li>C．核心</li><li>D．第三</li></ul><details class="quiz" data-q="56" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「最低」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 某高校校园网建设的一个项目经理，正在估算该项目的成本，此时尚未掌握项目的全部细节项目经理蜗牛 应该首先采用的成本估算方法是（ ）。</p><ul><li>A．类比估算法</li><li>B．自下而上估算法</li><li>C．蒙特卡罗分析</li><li>D．参数模型</li></ul><details class="quiz" data-q="57" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「类比估算法」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 关于成本估算方法的描述，正确的是（ ）。</p><ul><li>A．成本类比估算依赖于历史数据，其准确性与历史数据的相似性无关</li><li>B．参数估算的准确性取决于参数模型的成熟度和基础数据的可辈性</li><li>C．自下而上估算的准确性与单个工作包或活动的规模无关</li><li>D．参数估算不能与其他估算方法联合使用</li></ul><details class="quiz" data-q="58" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「参数估算的准确性取决于参数模型的成熟度和基础数据的可辈性」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 在成本估算过程中，成本估算的内容不包括（ ）。</p><ul><li>A．汇率</li><li>B．管理储备</li><li>C．通胀补贴</li><li>D．胜资成本</li></ul><details class="quiz" data-q="59" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：成本估算应覆盖项目所使用的全部资源，包括直接人工、材料、设备、服务、设施、信息技术，以及一些特殊的成本种类，如融资成本（包括利息）、通货膨胀补贴、江率或成本应急储盈（P344）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> 成本估算时，（ ）反映了因项目资金支出的周期而产生的资金制约因素。</p><ul><li>A．经验教训登记册F</li><li>B．资源需求</li><li>C．项目范围说明书</li><li>D．质量管理计划</li></ul><details class="quiz" data-q="60" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目范围说明书：项目范围说明书反映了因项目资金支出的周期而产生的资金制约因素，或其他财务假设条件和制约因素（P342）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 成本估算输出不包括（ ）。</p><ul><li>A．成本估算</li><li>B．估算依据</li><li>C．成本基准</li><li>D．融资成本</li></ul><details class="quiz" data-q="61" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：，成本基准属于制定预算的输出（P344-345）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> 某项目最可能的完工成本为900万元，乐观情况下700万元，悲观情况下1400万元，按照贝塔分布，期望值为（ ）万元。</p><ul><li>A．900</li><li>B．950</li><li>C．1000</li><li>D．1050</li></ul><details class="quiz" data-q="62" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：贝塔分布，期望值-（乐观时间+4×最可能时间土悲观时间）/6=950万元　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> （ ）利用历史数据之间的统计关系和其他变量，来进行项目工作的成本估算。</p><ul><li>A．类比估算</li><li>B．参数估算</li><li>C．自下而上估算</li><li>D．三点估算</li></ul><details class="quiz" data-q="63" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：参数估算：是利用历史数据之间的统计关系和其他变量进行估算（P343）　<span class="quiz-src">2018 年下半年高项</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> 关于成本估算的描述，正确的是（ ）。</p><ul><li>A．成本估算是在某特定时点，根据已知信息所做出来的成本预测</li><li>B．成本估算的准确性随着项目的进展而逐步下降</li><li>C．融资成本不应纳入成本估算</li><li>D．项目进度发生变化但范围没有变化，对成本估算不产生影响</li></ul><details class="quiz" data-q="64" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A正确。成本估算是在基特定时点，根据已知信息所做出的成本预测。B错误。成本估算准确性随着项目的进展逐渐精确。C错误。进行成本估算，应该考虑针对项目收费的全部资源，包括（但不限于）人工、材料、设备、服务、设施，以及一些特殊的成本种类，如通货膨胀补贴、融资成本或应急成本D错误（P341）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 关于成本估算的描述，正确的是（ ）。</p><ul><li>A．只能用货币单位进行成本估算，不能用人天数或人时数作为计量单位</li><li>B．通货膨胀补贴、融资成本不应纳入成本估算</li><li>C．参数估算可以针对整个项目，也可针对项目中的某个部分</li><li>D．应急储备用于应对项目中不可预知的风险</li></ul><details class="quiz" data-q="65" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：参数估算是指利用历史数据之间的统计关系和其他变量（如建筑施工中的平方英尺），来进行项目工作的成本估算，其准确性取决于参数模型的成熟度和基础数据的可靠性参数估算可以针对整个项目或项目中的基个部分，并可与其他估算方法联合使用（P343）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 用于估算成本的项目管理计划组件不包括（ ）。</p><ul><li>A．项目章程</li><li>B．范围基准</li><li>C．成本管理计划</li><li>D．质量管理计划</li></ul><details class="quiz" data-q="66" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：首先，项目章程不属于项目管理计划组件，这点就很容易判断出来估算成本过程输入的项目管理计划包括：成本管理计划、质量管理计划、范围基准（项目范围说明书、WBS、WBS字典）（P342）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 在估算成本过程中，（ ）是该过程的输入，（ ）是该过程的输出。</p><ul><li>A．工作分解结构(WBS)、资源需求</li><li>B．项目范围说明书、成本管理计划</li><li>C．资源需求清单、估算依据</li><li>D．历史信息、项目预算</li></ul><details class="quiz" data-q="67" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：342-345。资源盖求清单是该过程的输入，估算依据是该过程的输出　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> 某项目经理在估算某软件开发活动的成本时，发现该项目模块与历史项目高度相似，但当前项目要求引入AI技术，导致开发工作量增加10%，项目经理参考了历史项目的功能点成本数据，并结合AI技术的复杂度系数进行调整，最终得出活动成本估算值。项目经理主要使用了以下哪种技术（ ）。</p><ul><li>A．三点估算</li><li>B．类比估算</li><li>C．参数估算</li><li>D．储备分析</li></ul><details class="quiz" data-q="68" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：参数估算是指利用历史数据之间的统计关系和其他变量（如建筑施工中的平方英尺）来进行项目工作的成本估算，其准确性取决于参数模型的成熟度和基础数据的可靠性（P343）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> 与成本管理相关的描述中，正确的是（ ）。</p><ul><li>A．应急储备用来应对已识别风险，可以根据定量分析结果进行估算</li><li>B．管理储备是成本基准的一部分，用于应对已识别的“未知-未知”风险</li><li>C．应急储备可取成本估算值的某一百分比、某个固定值，或者通过定性分析来确定</li><li>D．随着项目信息越来越明确，可以动用、减少或取消管理储备</li></ul><details class="quiz" data-q="69" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：应急储备是包含在成本基淮内的一部分预算，用来应对已经接受的已识别风险，以及已经制定应急或减轻措施的已识别风险。应急储备通常是预算的一部分，用来应对那些会影响项目的“已知一未知”风险（P344）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> 某项目根据项目的规模（功能点数FP），并依据组织历史生产率数据（人时/FP）计算项目所需工作量，进而估算项目工期。该项目采用的估算方法是（ ）。</p><ul><li>A．专家判断</li><li>B．三点估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：参数估算是指利用历史数据之间的统计关系和其他变量（如建筑施工中的平方英尺），来进行项目工作的成本估算，其准确性取决于参数模型的成熟度和基础数据的可靠性（P343）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 估算成本时，应考虑材料、设备、服务、汇率、应急储备和管理储备6个因素中的（ ）个因素</p><ul><li>A．4</li><li>B．3</li><li>C．6</li><li>D．5</li></ul><details class="quiz" data-q="71" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：进行成本估算，应该考虑针对项目收费的全部资源，包括人工、材料、设备、服务、设施，以及一此特殊的成本种类，如通货膨胀补贴、融资成本或应急成本管理储备不在成本估算中考虑，是制定预算阶段由高层管理者设定的（P341）　<span class="quiz-src">2026 年高项第 2 批</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 制定预算是汇总所有单个活动或工作包的估算成本，建立一个经批准的成本基准的过程，其主要作用是（ ）。</p><ul><li>A．根据项目类型和复杂程度确定适用于项目资源的管理方法和管理程度</li><li>B．明确完成项目所需的资源种类、数量和特性</li><li>C．确定可据以监督和控制项目绩效的成本基准</li><li>D．在整个项目期间为如何管理和核实质量提供指南和方向</li></ul><details class="quiz" data-q="72" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：制定预算是汇总所有单个活动或工作包的估算成本，建立一个经批准的成本基准的过程。本过程的主要作用是确定可据以监督和控制项目绩效的成本基准（P345）　<span class="quiz-src">自编</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 制定预算时不需要考虑的因素是（ ）。</p><ul><li>A．成本管理计划</li><li>B．资源管理计划</li><li>C．项目资金需求</li><li>D．估算依据</li></ul><details class="quiz" data-q="73" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目资金需求是制定预算的输出（P345-346）　<span class="quiz-src">自编</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 制定预算过程的输入包括项目管理计划、项目文件等，其中项目管理计划中的（ ）描述如何将项目成本纳入项目预算；项目文件中的（ ）提供了成本估算的汇总依据；（ ）包含项目活动的计划开始和完成日期，可用于将成本汇总到相应日历时段。</p><ul><li>A．成本管理计划、成本估算、项目进度计划</li><li>B．资源管理计划、估算依据、风险登记册</li><li>C．成本管理计划、估算依据、项目进度计划</li><li>D．资源管理计划、成本估算、风险登记册</li></ul><details class="quiz" data-q="74" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：制定预算的输入中，项目管理计划里的成本管理计划，描述如何将项目成本纳入项目预算中项目文件中的成本估算，将各工作包内每个活动的成本估算汇总后，可得到各工作包的成本；项目进度计划包含项目活动、里程碑等的计划日期，可根据这些信息把计划成本和实际成本江总到相应日历时段（P346）　<span class="quiz-src">自编</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 通过在项目计划中添加强制日期解决资金计划和支出之间的差异，属于（ ）。</p><ul><li>A．资金储备分析</li><li>B．专家判断</li><li>C．成本汇总</li><li>D．资金限制平衡</li></ul><details class="quiz" data-q="75" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资金限制平衡：如果发现资金限制与计划支出之间存在差异，则可能需要调整工作的进度计划，以平衡资金的支出水平（P347）　<span class="quiz-src">自编</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 关于成本预算和成本基准的描述，不正确的是（ ）。</p><ul><li>A．成本预算是将已批准的项目总的估算成本分摊到项目的各项具体活动和各个具体项目阶段</li><li>B．多项目，特别是大项目，可能有多个成本基准</li><li>C．根据成本基准来确定总资金需求和阶段性（如季度或年度）资金需求</li><li>D．动用管理储备不会影响项目的成本基准</li></ul><details class="quiz" data-q="76" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：当出现有必要动用管理储备的变更时，则应该在获得变更控制过程的批准之后，把活量的管理储备移入成本基准中（P347-348）　<span class="quiz-src">自编</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 关于成本估算和预算的描述，不正确的是（ ）。</p><ul><li>A．成本估算的输出除了包括成本基准外，还应有估算依据</li><li>B．成本预算以成本估算为基础</li><li>C．成本预算是将项目成本分摊到项目的各个活动和各个阶段</li><li>D．项目预算是成本基准和管理储备之和</li></ul><details class="quiz" data-q="77" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A不正确，成本基准是制定预算的输出（P347-348）　<span class="quiz-src">自编</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 下列说法不正确的是（ ）。</p><ul><li>A．管理储备是用来应对会影响项目的“未知-未知”风险</li><li>B．管理储备不包括在成本基准中，也不包括在项目资金需求里</li><li>C．类比和参数模型预测的成本及准确性可能差别很大</li><li>D．成本基准是不同进度活动经批准的预算的总和</li></ul><details class="quiz" data-q="78" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：如果有管理储备，则总资金需求等于成本基准加管理储备。在资金需求文件中，也可说明资金来源（P348）　<span class="quiz-src">自编</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 成本基准是用来度量与监督项目成本绩效的按时间分段预算。下图中给出了某项目期望现金流、成本基准、资金需求情况。图中区间 A 应为（ ）。原题附图（略）：图中三条曲线分别为期望现金流、成本基准与资金需求。</p><ul><li>A．管理储备</li><li>B．成本偏差</li><li>C．进度偏差</li><li>D．超出的成本</li></ul><details class="quiz" data-q="79" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：虚线是资金需求，实线是成本基准，虚线汇总就是项目预算，实线汇总就是BAC，所以A是项目预算和BAC之差也就是管理储备。项目预算管理备 工资金需求支出成本基准时间图11-6 成本基准、支出与货金需求（P348）　<span class="quiz-src">自编</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 关于成本估算与预算的描述，不正确的是（ ）。</p><ul><li>A．成本估算的作用是确定完成工作所需的成本数额</li><li>B．成本基准是经过批准且按时间段分配的项目预算</li><li>C．如果发现资金限制与计划支出之间存在差异，则可能要调整工作的进度计划，以平衡资金的支出水平</li><li>D．项目预算包含应急储备，但不包含管理储备</li></ul><details class="quiz" data-q="80" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目预算包括管理储备（P348）　<span class="quiz-src">自编</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 某公司中标国外一地铁项目，要研发生产一批轨道交通设备。项目经理在估算工作成本2000万后，为防止政策变化预留了50万，为防止未知风险预留了100万，则该项目成本基准为（ ）万元。</p><ul><li>A．2000</li><li>B．2050</li><li>C．2100</li><li>D．2150</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「2000」，原解析未给课本依据　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 在项目管理中，（ ）不是制定预算过程的输入。</p><ul><li>A．成本管理计划</li><li>B．项目资金需求</li><li>C．资源管理计划</li><li>D．成本估算</li></ul><details class="quiz" data-q="82" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目资金需求是制定预算过程的输出（P348）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 关于成本基准的描述，不正确的是（ ）。</p><ul><li>A．成本基准是汇总了所有单个活动或工作包的估算成本，并经过批准的时间分段的预算</li><li>B．当项目动用管理储备以应对未知风险时，成本基准不会因此发生改变</li><li>C．成本基准是经过批准的、按时间段分配的项目预算，不包括任何管理储备</li><li>D．成本基准中既包括项目的直接成本，也包括间接成本，如融资成本、管理费用分摊等</li></ul><details class="quiz" data-q="83" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：当出现有必要动用管理储备的变更时，则应该在获得变更控制过程的批准之后，把适量的管理储备移入成本基准中　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> 制定项目预算，工作包汇总为320万元，应急储备为30万元，另外批准20万元管理储备。成本基准应为（ ）万元。</p><ul><li>A．370</li><li>B．350</li><li>C．320</li><li>D．330</li></ul><details class="quiz" data-q="84" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：347。成本基准是经过批准的、按时间段分配的项目预算，不包括任何管理储备，只有通过正式的变更控制程序才能变更，用作与实际结果进行比较的依据，成本基准是不同进度活动经批准的预算的总和　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> 成本管理分为成本估算、成本预算和成本控制三个过程，以下关于成本预算的叙述中，不正确的是（ ）</p><ul><li>A．成本预算过程完成后，可能会引起项目管理计划的更新</li><li>B．管理储备是为范围和成本的潜在变化而预留的预算，需要体现在项目成本基线中</li><li>C．成本基准计划可以作为度量项目绩效的依据</li><li>D．成本基准按时间分段计算，通常以S曲线的形式表示</li></ul><details class="quiz" data-q="85" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：选项A正确。成本预算完成后，会产出“成本基准”，而成本基准是项目管理计划的重要组成部分。如果预算过程中调整了资源分配、时间安排等，自然会引起项目管理计划的更新选项B错误（P347-348）　<span class="quiz-src">2016 年上半年高项</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 项目经理卧年刚刚完成一个小项目的启动阶段，开始步入计划编制阶段，这时，公司主管经营的副总经理向项目经理索要项目预算和成本基准计划。该项目经理较恰当的回答（ ）。</p><ul><li>A．可以在项目章程中找到项目预算，项目章程刚刚做完</li><li>B．在计划编制阶段完成之前，项目预算和基准计划是不能最终确定的</li><li>C．项目计划将不包括项目预算和基准计划，这是个小项目</li><li>D．在制定项目计划之前不可能完成估算</li></ul><details class="quiz" data-q="86" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：计划编制阶段：项目经理需要在这个阶段进行详细的活动定义、排序、资源估算、成本估算，最后汇总形成成本基准和项目预算。在计划编制阶段彻底完成之前，这些详细的基准是无法最终确定的　<span class="quiz-src">自编</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 项目经理在进行预算方案编制时，收集到的基础数据如下：工作包的成本估算为40万元；工作包的应急储备金为4万元；管理储备金为2万元。该项目的成本基准是（ ）万元</p><ul><li>A．40</li><li>B．44</li><li>C．42</li><li>D．46</li></ul><details class="quiz" data-q="87" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：成本基准-估算成本+应急储备=44万项目预算 管理储备成本盛准 控制账户 应急储备工作包成本 话动应急储备估算 活动成本估算项目预算的组成图11一4 项目预算的组成（P347-348）　<span class="quiz-src">2017 年上半年高项</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> （ ）不属于制定预算过程的输出。</p><ul><li>A．成本基准</li><li>B．范围基准</li><li>C．项目资金需求</li><li>D．更新的活动成本估算</li></ul><details class="quiz" data-q="88" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：B错误。范围基准是创建 WBS的输出、D没有问题，可在制定预算过程更新的项目文件主要包括：成本估算、更新成本估算，以记录任何额外信息（P347-348）　<span class="quiz-src">2018 年上半年高项</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 关于成本管理的描述，不正确的是（ ）。</p><ul><li>A．成本基准不包括管理储备</li><li>B．成本基准中包括预计的支出，但不包括预计的债务</li><li>C．管理储备用来应对会影响项目的“未知-未知”风险</li><li>D．成本基准是经过批准且按时间段分配的项目预算</li></ul><details class="quiz" data-q="89" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：AC正确。管理储备不包括在成本基准中，但属于项目总预算和资金需求的一部分，管理储备用来应对会影响项目的“未知-未知”风险（P347-348）　<span class="quiz-src">2019 年下半年高项</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 关于项目成本预算的描述，不正确的是（ ）。</p><ul><li>A．范围基准、风险登记册和活动成本估算是制定预算过程的有效输入</li><li>B．资源日历中可获得项目资源种类和使用时间，以确定各阶段的资源成本</li><li>C．做项目成本预算时，需要按照正态分布规律，依时间段分配成本</li><li>D．成本基准是经过批准的，包括应急储备，但不包括管理储备</li></ul><details class="quiz" data-q="90" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目资金通常以增量面非连续的方式投入，并且可能是非均衡的，呈现出阶梯状。所以C不止确（P348）　<span class="quiz-src">2021 年上半年高项</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> 关于制定预算的描述，不正确的是（ ）。</p><ul><li>A．成本基准是经过批准且按时间段分配的项目预算</li><li>B．项目总资金需求是根据资金投入计算出的成本基准</li><li>C．成本基准中的成本估算与进度活动直接关联</li><li>D．项目资金通常以增量而非连续的方式投入</li></ul><details class="quiz" data-q="91" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：ACD正确。B错误。如果有管理储备，则总资金需求等于成本基准加管理储盆（P348）　<span class="quiz-src">2022 年上半年高项</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> （ ）属于成本基准。①管理储备；②应急储备；③材料成本；④服务费</p><ul><li>A．①③④</li><li>B．①②③</li><li>C．①②④</li><li>D．②③④</li></ul><details class="quiz" data-q="92" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：成本基准不包含管理储备（P347-348）　<span class="quiz-src">2022 年下半年高项</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 小李管理了一个项目，该项目包含3个模块，各模块的成本分别为6、8、9万，为了应对风险，小李特意预留了2万的管理储备，3万的应急储备，请问小李的项目的成本基准是（ ）</p><ul><li>A．23万</li><li>B．25万</li><li>C．26万</li><li>D．28万</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：成本基准=6+8+9+3-26万，管理储备不在成本基准中（P348）　<span class="quiz-src">2023 年下半年高项第 1 批</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> 某项目投资20万，考虑到风险，预留了10%管理储备和5%应急储备，则该项目的总预算为（ ）。</p><ul><li>A．2O万</li><li>B．21万</li><li>C．23万</li><li>D．22万</li></ul><details class="quiz" data-q="94" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：应急储备为205%-1万，管理储备为2010%-2万。所以总预算为20+1+2-23万。总预算是包含管理储备的（P348）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> 在制定预算的过程中，可以使用以下哪种工具或技术（ ）</p><ul><li>A．三点估算</li><li>B．类比估算</li><li>C．历史信息审核</li><li>D．完工尚需绩效指数</li></ul><details class="quiz" data-q="95" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：制定预算的工具与技术：1专家判断2.成本汇总3数据分析4历史信息审核5资金限制平衡6.融资（P346）　<span class="quiz-src">2023 年下半年高项第 3 批</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 项目预算与成本基准之间的差额是（ ）。</p><ul><li>A．应急储备</li><li>B．应付未付的成本</li><li>C．管理储备</li><li>D．应收未收的收入</li></ul><details class="quiz" data-q="96" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：项目预算与成本基准之间的差额是管理储备。项目预解管理铭备成本基准 控感户应急储备工作色应本 活动应急储备估算 动成本估算项目预算的组成图11-4 项目预算的组咸（P348）　<span class="quiz-src">2023 年下半年高项第 4 批</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 关于制定预算的描述，不正确的是（ ）。</p><ul><li>A．项目预算包括经批准用于执行项目的全部资金</li><li>B．成本基准是经过批准且按时间段分配的项目预算</li><li>C．制定预算过程的主要作用是确定项目所需资金</li><li>D．制定预算是汇总所有单个活动或工作包的估算成本，建立一个经批准的成本基准的过程</li></ul><details class="quiz" data-q="97" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：制定预算是汇总所有单个活动或工作包的估算成本，建立一个经批准的成本基准的过程。本过程的主要作用是，确定可以依据其来进行监督和控制项目绩效的成本基准（P345）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 制定预算过程的主要输出是（ ），控制成本过程的主要输出是（ ）。</p><ul><li>A．成本估算、成本基准</li><li>B．成本基准、成本预测</li><li>C．成本预测、成本估算</li><li>D．成本管理计划、成本基准</li></ul><details class="quiz" data-q="98" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：P347。制定预算过程的主要输出：1成本基准；2，项目资金需求；3项目文件更新（成本估算、项目进度计划、风险登记册）。P355（P347-355）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 在项目成本管理中，（ ）是制定预算过程的输入，（ ）是制定预算过程的输出。</p><ul><li>A．风险登记册、成本预测</li><li>B．项目资金需求、成本基准</li><li>C．协议、成本基准</li><li>D．成本估算、变更请求</li></ul><details class="quiz" data-q="99" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：P348、制定预算过程的输入包括：1项目管理计划（成本管理计划、资源管理计划、范围基准）2.可行性研究文件（可行性研究报告、项目评估报告）;3.项目文件（估算依据、成本估算、项目进度计划、风险登记册）;4.协议；5事业环境因素；6.组织过程资产；制定预算过程的输出包括：1成本基准；2.项目资金需求；3.项目文件更新（成本估算、项目进度计划、风险登记册）;（P345）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 下列关于项目预算的描述中，不正确的是（ ）。</p><ul><li>A．对于使用挣值管理的项目，成本基准指的是绩效测量基准</li><li>B．项目资金通常以均衡增量的方式投入</li><li>C．如果有管理储备，则总资金需求等于成本基准加管理储备</li><li>D．汇总各控制账户的成本可得成本基准</li></ul><details class="quiz" data-q="100" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：ACD都是教材原话，B不正确，项目资金通常以增量的方式投入，并且可能是韭均衡的（P348）　<span class="quiz-src">2026 年高项第 1 批</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 在EVM中，偏差分析用以解释成本偏差、进度偏差和完工偏差的原因、影响和纠正措施。其中完工偏差的表达公式是（ ）</p><ul><li>A．CV=EV-AC</li><li>B．VAC=BAC-EAC</li><li>C．SV=EV-PV</li><li>D．EAC=AC+(BAC-EV)</li></ul><details class="quiz" data-q="101" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：对预算亏空或盈余量的 正值=低于计划成本项目完成时的成本估完工 正好0-按计划咸本一种预测。是完工预算vC VMC=BMC-EMC偏差 算差距与完工估算之差 负值=超出计划成本（P354）　<span class="quiz-src">教材第 11 章章节习题</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 下列活动中需要在整个项目期间持续开展的是（ ）</p><ul><li>A．规划成本管理</li><li>B．估算成本</li><li>C．制定预算</li><li>D．控制成本</li></ul><details class="quiz" data-q="102" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制成本需要在整个项目期间开展（P349）　<span class="quiz-src">自编</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> （ ）的主要作用是，在整个项目期间保持对成本基准的维护。</p><ul><li>A．规划成本管理</li><li>B．估算成本</li><li>C．制定预算</li><li>D．控制成本</li></ul><details class="quiz" data-q="103" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制成本的主要作用是，在整个项目期间保持对成本基准的维护（P349）　<span class="quiz-src">自编</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 有效成本控制的关键在于管理经批准的（ ）。</p><ul><li>A．成本估算</li><li>B．成本预算</li><li>C．成本基准</li><li>D．管理储备</li></ul><details class="quiz" data-q="104" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：有效成本控制的关键在于管理经批准的成本基准（P349）　<span class="quiz-src">自编</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 项目成本控制的目标不包括（ ）。</p><ul><li>A．对造成成本基准变更的因素施加影响</li><li>B．确保成本支出不超过批准的资金限额</li><li>C．对照资金支出，监督工作绩效</li><li>D．更新成本基准</li></ul><details class="quiz" data-q="105" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目成本控制的目标包括：●对造成成本基准变更的因素施加影响；●确保所有变吏请求都得到及时处理；●当变吏实际发生时，管理这些变更；确保成本支出不超过批准的资金限额，既不超出按时段、按WBS组件、按活动分配的限额，也不超出项目总限额；●监督成本绩效，找出并分析与成本基准间的偏差；●对照资金支出，监怪工作绩效；●防止在成本或资源使用报告中出现未经批准的变更；●向干系人报告所有经批准的变更及其相关成本；●…（P349）　<span class="quiz-src">自编</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 以下关于成本基准特点的叙述中，不正确的是（ ）。</p><ul><li>A．按时间分段计算，用做度量和监督成本绩效的基准</li><li>B．成本基准反映整个项目生命期的实际成本支出</li><li>C．按时段汇总估算的成本编制而成</li><li>D．通常以S曲线的形式表示</li></ul><details class="quiz" data-q="106" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：O。实际成本(AC):是在给定时段内执行基活动面实际发生的成本，是为完成与EV相对应的工作面发生的总成本。项目生命期的实际成本支出和成本基准没有关系，在控制成本的时候需要比较二者间的关系，判断是否需要纠偏（P35）　<span class="quiz-src">自编</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> 下列说法不正确的是（ ）。</p><ul><li>A．项目资金需求包括预计支出，但不包括预计债务</li><li>B．成本控制中，应重点分析项目资金支出与完成的相应工作之间的关系，有效成本控制的关键在于管理经批准的成本基准</li><li>C．成本控制的主要作用是在整个项目期间保持对成本基准的维护</li><li>D．成本控制需要在整个项目期间开展</li></ul><details class="quiz" data-q="107" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目资金需求包括预计支出及预计债务（P350）　<span class="quiz-src">自编</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．计划价值(PV)，是为计划工作分配的经批准的预算，不包括管理储备</li><li>B．挣值(EV)，是对已完成工作的测量值，是已完成工作的经批准的预算</li><li>C．实际成本(AC)，是在给定时段内执行某活动而实际发生的成本，是为完成与EV相对应的工作而发生的总成本</li><li>D．AC需要根据计划价值(PV)来调整，不得超过计划价值</li></ul><details class="quiz" data-q="108" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：AC没有上限，为实现EV所花费的任何成本都要计算进去（P350-351）　<span class="quiz-src">自编</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 以下说法不正确的是（ ）。</p><ul><li>A．进度偏差(SV=EV-PV)，表示为挣值与计划价值之差</li><li>B．成本偏差(CV-EV-AC)，是在某个给定时点的预算亏空或盈余量，表示为挣值与实际成本之差</li><li>C．进度绩效指数(SP-EV/PV)，是测量进度效率的一种指标，表示为挣值与计划价值之比</li><li>D．成本偏差CV值如果出现小于零的情况，可以在之后的工作中加强管理，以挽回之前的CV值</li></ul><details class="quiz" data-q="109" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：CV为负值一般都是不可挽回的。成本偏差CV值是在基个给定时点的预算亏空或盈余量，一旦是负值是不可掩回的。即使在之后的工作中加强管理，那也是对之后的工作绩效进行纠偏，对之前的CV值没有影响，（P351）　<span class="quiz-src">自编</span></p></details><p><a id="q110" class="quiz-anchor"></a></p><p><strong>110.</strong> 项目经理小张对自己正在做的一个项目进行挣值分析后，发现CPR&gt;1，则可以判断该项目（ ）</p><ul><li>A．进度超前</li><li>B．进度落后</li><li>C．成本超支</li><li>D．成本节约</li></ul><details class="quiz" data-q="110" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：大于1“低于计戈CPI为1意味着项目成本测量预算资源的成本效成本 完全按照预算进行 CPI=EV/ACCP 绩效 率的指标，表示为挣值 正好按计划成本其他值表示超出或者指数 与实际成本之比 小于1=超出计划成低于预算的比例（P354）　<span class="quiz-src">自编</span></p></details><p><a id="q111" class="quiz-anchor"></a></p><p><strong>111.</strong> 控制成本时不需要考虑的因素是（ ）。</p><ul><li>A．成本预测</li><li>B．成本基准</li><li>C．绩效测量基准</li><li>D．工作绩效数据</li></ul><details class="quiz" data-q="111" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：成本预测是控制成本的输出。控制成本的输入包括：1项目管理计划（成本管理计划、成本基准、绩效测量基准）;2.项目资金需求；3项目文件；4工作绩效数据；5组织过程资产（P355）　<span class="quiz-src">自编</span></p></details><p><a id="q112" class="quiz-anchor"></a></p><p><strong>112.</strong> 控制成本过程中，需以（ ）为依据，结合项目资金需求，通过（ ）分析成本偏差，同时将工作绩效信息输出给（ ）过程，确保成本管控合规。</p><ul><li>A．成本基准、偏差分析、监控项目工作</li><li>B．项目预算、趋势分析、结束项目或阶段</li><li>C．成本管理计划、储备分析、指导与管理项目执行</li><li>D．范围基准、挣值分析、规划成本管理</li></ul><details class="quiz" data-q="112" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制成本过程需以成本基准为依据，确保成本支出不偏离基准；偏差分析是控制成本的工具，用于分析实际成本与基准的偏差；控制成本产生的工作绩效信息需输出给监控项目工作过程，用于整体项目绩效监控（P349-355）　<span class="quiz-src">自编</span></p></details><p><a id="q113" class="quiz-anchor"></a></p><p><strong>113.</strong> 关于成本管理的描述，正确的是（ ）。</p><ul><li>A．当项目完工时，成本偏差(CV)可能为零，也可能不为零</li><li>B．项目资金需求不包括预计债务</li><li>C．当面对未知-未知的风险时，项目经理可以调用部分应急储备</li><li>D．项目团队差旅费、人力资源部的工资可以归属于项目工作的直接成本</li></ul><details class="quiz" data-q="113" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：A正确。CV-EV-AC，项目完工时，可能为零，也可能不为零；B错误。项目资金需求包括预计支出及预计债务；C错误。应急储备用在应对已知-未知的风险；D错误（P354-356）　<span class="quiz-src">自编</span></p></details><p><a id="q114" class="quiz-anchor"></a></p><p><strong>114.</strong> 如果项目实际进度比计划提前20%，实际成本只用了预算成本的60%，首先应该（ ）</p><ul><li>A．重新修订进度计划</li><li>B．给项目团队加薪，开表影大会</li><li>C．重新进行成本预算</li><li>D．找出与最初计划产生差别的原因</li></ul><details class="quiz" data-q="114" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「找出与最初计划产生差别的原因」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q115" class="quiz-anchor"></a></p><p><strong>115.</strong> 某项目经理承接一个软件开发项目，项目执行过程中，通过挣值分析得出：挣值(EV)-80万元，计划价值(PV)-100万元，实际成本(AC)-90万元。部分已识别风险未发生，应急储备有结余。针对该场景，项目经理最适合的做法是（ ）。</p><ul><li>A．忽略成本与进度偏差，继续按原计划执行</li><li>B．分析成本超支和进度落后原因，采取纠正措施，同时扣除未使用的应急储备</li><li>C．申请增加项目预算，弥补成本超支，加快进度追赶计划</li><li>D．采取纠正措施，投入应急储备，加快进度追赶计划</li></ul><details class="quiz" data-q="115" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：正确项为「分析成本超支和进度落后原因，采取纠正措施，同时扣除未使用的应急储备」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q116" class="quiz-anchor"></a></p><p><strong>116.</strong> 项目经理估算出某项目的总成本需要 100 万，为应对一个已识别的风险，预留了 10 万的应急金，为了增加团队士气，预留了 3 万的团建费用。上报后，财务总监认为该风险已经有过类似的应对方案，只同意批准 5 万应急金，另外团建费用也未通过审批，最终批准下来的金额是 95 万，该项目的成本基准是（ ）。</p><ul><li>A．95</li><li>B．97</li><li>C．100</li><li>D．105</li></ul><details class="quiz" data-q="116" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：正确项为「95」，原解析未给课本依据　<span class="quiz-src">自编</span></p></details><p><a id="q117" class="quiz-anchor"></a></p><p><strong>117.</strong> 控制成本过程中，如果当前偏差被视为典型偏差，且将继续影响项目时，ETC的计算公式为（ ）</p><ul><li>A．ETC=(BAC-CV)/CPI</li><li>B．ETC=BAC-EV</li><li>C．ETC=BAC-CV</li><li>D．ETC=(BAC-EV)/CPI</li></ul><details class="quiz" data-q="117" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：在计算EAC时，通常用已完成工作的实际成本(AC)，加上剩余工作的完工尚需估算(ETC)，即：EAC-AC+ETC。两种最常用的计算ETC的方法●基于非典型的偏差计算ETC（P352）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q118" class="quiz-anchor"></a></p><p><strong>118.</strong> 有效成本控制关键在于管理经批准的（ ）。</p><ul><li>A．成本估算</li><li>B．成本基准</li><li>C．项目预算</li><li>D．绩效测量基准</li></ul><details class="quiz" data-q="118" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：349。控制成本是监督项目状态，以更新项目成本和管理成本基准变更的过程本过程的主要作用是，在整个项目期间保持对成本基准的维护　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q119" class="quiz-anchor"></a></p><p><strong>119.</strong> PV=100,AC=80,EV=70，判断项目绩效（ ）。</p><ul><li>A．成本节约，进度提前</li><li>B．成本节约，进度滞后</li><li>C．成本超支，进度提前</li><li>D．成本超支，进度滞后</li></ul><details class="quiz" data-q="119" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：CV-EV-AC-70-80=10，成本超支，SV-EV-PV-70-100=30，进度滞后　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q120" class="quiz-anchor"></a></p><p><strong>120.</strong> 关于控制成本过程的目标的描述，不正确的是（ ）。</p><ul><li>A．控制成本过程应确保项目成本支出不超过申报的资金限额</li><li>B．控制成本过程中应监督成本绩效，找出并分析与成本基准间的偏差</li><li>C．控制成本过程中可对照资金支出，监督工作绩效</li><li>D．控制成本过程对造成成本基准变更的因素施加影响</li></ul><details class="quiz" data-q="120" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：349。控制成本的限额依据是成本基准，不是“申报的资金限额”。申报资金只是前期申请金额，成本基准是经过批准、受控的预算基线，项目成本管控以成本基准为准正确描述为：确保成本支出不超过批准的资金限额，既不超出按时段、按WBS组件、按活动分配的限额，也不超出项目总限额　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q121" class="quiz-anchor"></a></p><p><strong>121.</strong> 项目经理小李对自己的项目采用挣值法进行分析后，发现sPI&gt;1、CPl&lt;1。则该项目（ ）</p><ul><li>A．进度超前，成本节约</li><li>B．进度超前，成本超支</li><li>C．进度延后，成本节约</li><li>D．进度延后，成本超支</li></ul><details class="quiz" data-q="121" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：SPI&gt;1，进度超前，CPI&lt;1，成本超支（P354）　<span class="quiz-src">2016 年下半年高项</span></p></details><p><a id="q122" class="quiz-anchor"></a></p><p><strong>122.</strong> 控制成本过程输出不包括（ ）。</p><ul><li>A．项目资金需求</li><li>B．项目文件更新</li><li>C．工作绩效信息</li><li>D．成本预测</li></ul><details class="quiz" data-q="122" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目资金需求是制定预算的输出。控制成本的输出包括：1工作绩效信息；2.成本预测；3变更请求；4.项目管理计划更新（成本管理计划、成本基准、绩效测量基准）;5项目文件更新（假设日志、估算依据、成本估算、经验教训登记册、风险登记册）（P355-356）　<span class="quiz-src">2018 年下半年高项</span></p></details><p><a id="q123" class="quiz-anchor"></a></p><p><strong>123.</strong> 关于控制成本数据分析技术的描述，不正确的是（ ）。</p><ul><li>A．项目的总计划价值又被称为完工预算(BAC)</li><li>B．为实现挣值(EV)所花费的任何成本都应计入实际成本(AC)</li><li>C．当项目完工时，进度偏差(SV)可能为零，也可能不为零</li><li>D．项目结束时的成本偏差(CV)是完工预算与实际成本之间的差值</li></ul><details class="quiz" data-q="123" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：当项目完工时，全部的计划价值都将实现（即成为挣值），进度偏差最终将等于零（P350-351）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q124" class="quiz-anchor"></a></p><p><strong>124.</strong> 以下（ ）不属于成本控制的内容。</p><ul><li>A．对造成成本基准变更的因素施加影响</li><li>B．防止在成本或资源使用报告中出现未经批准的变更</li><li>C．向干系人报告所有经批准的变更及其相关成本</li><li>D．确定可以依据其来进行监督和控制项目绩效的成本基准</li></ul><details class="quiz" data-q="124" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：D是成本预算的内容。项目成本控制的目标包括：①对造成成本基准变更的因素施加影响；②确保所有变更请求都得到及时处理；③当变更实际发生时，管理这些变更；“④确保成本支出不超过批准的资金限额，既不超出按时段、WBS组件和活动分配的限额，也不超出项目总限额（P349）　<span class="quiz-src">2023 年下半年高项第 2 批</span></p></details><p><a id="q125" class="quiz-anchor"></a></p><p><strong>125.</strong> 某项目的项目经理在成本控制过程中，发现成本偏差(CV)呈现负值，为了采取有效的纠正措施，优先策略是（ ）。</p><ul><li>A．降低项目质量要求，以实现更高的成本效益</li><li>B．识别并减少冗余活动的工作量，以降低成本</li><li>C．减少合同交付内容，以减少成本负担</li><li>D．增加项目范围，以提高收入来降低成本超支</li></ul><details class="quiz" data-q="125" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：CV呈现负值，说明成本超支；本道题考的比较灵活，问的是优先策略，也就是说只能从4个选项中优中选优。通过分析得出：选项A，可能造成质量风险，有问题；选项B，识别并减少冗余活动的工作量，提高工作效率，降低成本，做法比较好；选项C，减少合同交付内容，肯定不行；选项D，增加项目范围，这个也不行；（P351）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q126" class="quiz-anchor"></a></p><p><strong>126.</strong> 某项目的完工预算(BAC)为560万元，实际成本(AC)为200万元，挣值(EV)为160万元。项目经理发现一个已识别的风险发生，需额外支出20万元。同时，团队新识别了一个高风险，预计需30万元应对，但该风险未在风险登记册中记录。如果按照当前绩效，项目经理重新计算完工估算(EAC)的值是（ ）。</p><ul><li>A．63O万元</li><li>B．73O万元</li><li>C．65O万元</li><li>D．75O万元</li></ul><details class="quiz" data-q="126" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：正确项为「75O万元」，原解析未给课本依据　<span class="quiz-src">2025 年高项第 2 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};